function filterByChart(type,idx){
  var val=type=='prov'?topProvFull[idx]:topProjFull[idx];
  var table=document.getElementById('facturasObraTable');
  var rows=table.querySelectorAll('tbody tr');
  var colIdx=type=='prov'?4:0;
  var shown=0;
  rows.forEach(function(row){
    var cells=row.querySelectorAll('td');
    if(cells.length>colIdx){
      var txt=cells[colIdx].textContent.toLowerCase();
      if(txt.indexOf(val.toLowerCase())>=0){row.style.display='';shown++;}
      else{row.style.display='none';}
    }
  });
  var badge=document.getElementById('activeFilterBadge');
  badge.style.display='inline';badge.textContent=type=='prov'?'Proveedor: '+val:'Proyecto: '+val;
  document.getElementById('clearFilterBtn').style.display='inline';
  document.getElementById('clearFilterBtn').scrollIntoView({behavior:'smooth',block:'center'});
}
function clearChartFilter(){
  var rows=document.getElementById('facturasObraTable').querySelectorAll('tbody tr');
  rows.forEach(function(row){row.style.display='';});
  document.getElementById('activeFilterBadge').style.display='none';
  document.getElementById('clearFilterBtn').style.display='none';
  document.querySelector('.search-box').value='';
}
